export class CreateCreditDto {
    /**
     * The unique identifier for the SaaS business
     * @example HarperDB
     */
    @ApiHideProperty()
    @IsString()
    @IsOptional()
    public businessID: string;
    /**
     * Unique identifier assigned by Paigo
     * <br><br>
     * Example: `"e345f409-daca-4144-91d2-0a0f87c96581"`
     * @example "e345f409-daca-4144-91d2-0a0f87c96581"
     */
    @ApiHideProperty()
    @IsString()
    @IsUUID()
    @IsOptional()
    public customerId: string;
    /**
     * The amount to credit the customer. Can be positive or negative. Customers cannot have a negative balance set via the API.
     * <br><br>
     * Example: `"100.00"`
     * @example "100.00"
     * @example "100"
     **/
    @IsNotEmpty()
    @Transform(({ value }) => parseFloat(value))
    @Min(-1000000000)
    @Max(1000000000)
    @IsNumber()
    @ApiProperty({ type: 'string', maximum: 1000000000, minimum: -1000000000 })
    public transactionAmount: string;
    /**
     * The timestamp of the credit. Optional. Will be set to right now UTC if not provided.
     * <br><br>
     * Example: `"2021-01-01T00:00:00.000Z"`
     * @example "2021-01-01T00:00:00.000Z"
     **/
    @IsString()
    @IsOptional()
    @IsRFC3339()
    public timestamp?: string;
    /**
     * The metadata to attach to the credit. Optional
     * <br><br>
     * Example: `{"key": "value"}`
     * @example {"key": "value"}
     **/
    @IsOptional()
    @IsObject()
    public metadata?: Record<string, string>;

    /**
     * When true, allows the resulting balance to be negative. Internal use only.
     */
    @ApiHideProperty()
    @IsOptional()
    @IsBoolean()
    public allowNegativeBalance?: boolean;
}

    async create(
        { transactionAmount, businessID, customerId, metadata, timestamp, allowNegativeBalance }: CreateCreditDto,
        validateCustomer?: boolean,
    ): Promise<{ message: string; transactionRow: ReadTransactionLedger }> {
        if (validateCustomer) {
            await this.customerService.findOne({ customerId, businessID });
        }
        const entity = new CreditEntity({ businessID, transactionAmount, customerId, metadata, timestamp });
        const { balance } = await this.findCreditBalance({ businessID, customerId }, false);
        if (!allowNegativeBalance && parseFloat(balance) + parseFloat(transactionAmount as unknown as string) < 0) {
            throw new ConflictException('Cannot create credit transaction that would result in a negative balance');
        }
        const points = CreditEntity.transform({ creditEntity: entity, influxService: this.InfluxService });
        await this.InfluxService.loadPoints(`${process.env.STAGE}-config`, process.env.INFLUX_ORG, points);
        return {
            message: 'Successfully updated customer credit',
            transactionRow: new ReadTransactionLedger(entity),
        };
    }
}

