        @Inject(forwardRef(() => CustomerService)) readonly customerService: CustomerService,
        @Inject(forwardRef(() => UserEntitlements)) readonly userEntitlements: UserEntitlements,
        @Inject(forwardRef(() => TokenConsumerService)) readonly tokenConsumerService: TokenConsumerService,
        @Inject(forwardRef(() => SchedulerService)) readonly schedulerService: SchedulerService,
    ) {}

    private validateTopUpFields(dto: {
        billingCycle?: ValidBillingCycles;
        topUpAmount?: string;
        topUpThreshold?: string;
        offeringType?: string;
    }) {
        const billingCycle = dto.billingCycle ?? ValidBillingCycles.monthly;
        if (dto.offeringType === OfferingType.subscription && billingCycle === ValidBillingCycles.topUp) {
            throw new BadRequestException('Subscription offerings cannot use topUp billing cycle');
        }
        if (billingCycle === ValidBillingCycles.topUp) {
            if (!dto.topUpAmount) {
                throw new BadRequestException('topUpAmount is required for topUp billing cycle');
            }
        } else {
            if (dto.topUpAmount !== undefined && dto.topUpAmount !== null) {
                throw new BadRequestException('topUpAmount is only valid for topUp billing cycle');
            }
            if (dto.topUpThreshold !== undefined && dto.topUpThreshold !== null) {
                throw new BadRequestException('topUpThreshold is only valid for topUp billing cycle');
            }
        }
    }

    private async createTopUpScheduler({
        businessID,
        offeringId,
        subject,
    }: {
        businessID: string;
        offeringId: string;
        subject: string;
