        await this.schedulerService.create({
            schedulerID: offeringId,
            schedulerType: schedulerType.dimensionDataGathering,
            schedulerStatus: SchedulerStatus.live,
            scheduleParameters: {
                dimensionType: 'offeringTopUpChecker',
                businessID,
                offeringId,
            },
            rate: SupportedMeasurementFrequencies.everyHour,
            subject,
            businessID,
        });
    }

    private async removeTopUpScheduler({ businessID, offeringId }: { businessID: string; offeringId: string }) {
        try {
            await this.schedulerService.remove({ schedulerID: offeringId, businessID });
        } catch (e) {
            if (!(e instanceof NotFoundException)) {
                throw e;
            }
        }
    }

