import { IsNotEmpty, IsString } from 'class-validator';

export class OfferingTopUpCheckerDto {
    /**
     * Static string indicating the dimensionType / processor name
     */
    @IsString()
    @IsNotEmpty()
    public dimensionType: 'offeringTopUpChecker';

    @IsString()
    @IsNotEmpty()
    public offeringId: string;

    @IsString()
    @IsNotEmpty()
    public businessID: string;
}

import { Job } from 'bull';
import { SchedulerEntity } from '../../scheduler/entities/scheduler.entity.js';
import { OnQueueFailed, Process, Processor } from '@nestjs/bull';
import { OfferingTopUpCheckerDto } from './dto/offeringTopUpChecker.dto.js';
import { Inject, Logger, forwardRef } from '@nestjs/common';
import { CustomerService } from '../../customer/customer.service.js';
import { AuditService } from '../../audit/audit.service.js';
import { AuditScope } from '../../audit/entities/audit.interface.js';
import { ContractService } from '../../contract/contract.service.js';
import { UsageBased } from '../../offering/entities/offeringPackage.entity.js';
import { serializeError } from 'serialize-error';

@Processor('scheduler_queue')
export class OfferingTopUpChecker {
    private static readonly logger = new Logger(OfferingTopUpChecker.name);
    constructor(
        @Inject(forwardRef(() => CustomerService)) readonly customerService: CustomerService,
        @Inject(forwardRef(() => ContractService)) readonly contractService: ContractService,
    ) {}

    @Process('offeringTopUpChecker')
    async processTopUp({ data: { scheduleParameters } }: Job<SchedulerEntity>) {
        const { businessID, offeringId } = scheduleParameters as OfferingTopUpCheckerDto;
        OfferingTopUpChecker.logger.log(
            `Starting top-up checker for offering ${offeringId} business ${businessID}`,
        );
        try {
            const { data: customers } = await this.customerService.findAllCustomersWithOfferingId({
                businessID,
                offeringId,
            });
            await Promise.all(
                (customers || []).map(async (customer) => {
                    try {
                        const { offering } = await this.contractService.findOne({
                            customerId: customer.customerId,
                            businessID,
                            offeringId,
                            offeringEnrollmentDate: customer?.offeringEnrollmentDate,
                            freeTrialEndDate: customer?.freeTrialEndDate,
                        });
                        if (offering instanceof UsageBased && typeof offering.processHourlyTopUp === 'function') {
                            await offering.processHourlyTopUp({ customer });
                        } else if (offering && typeof (offering as UsageBased).topUp === 'function') {
                            await (offering as UsageBased).processHourlyTopUp({ customer });
                        }
                    } catch (error) {
                        OfferingTopUpChecker.logger.error(
                            `Failed top-up for customer ${customer?.customerId}`,
                            serializeError(error),
                        );
                        AuditService.publishEvent({
                            message: 'Failed to process top-up for customer',
                            topic: AuditScope.ERROR,
                            data: [
                                {
                                    error: serializeError(error),
                                    customerId: customer?.customerId,
                                    businessID,
                                    offeringId,
                                },
                            ],
                        });
                    }
                }),
            );
        } catch (error) {
            OfferingTopUpChecker.logger.error('Failed offering top-up checker', serializeError(error));
            AuditService.publishEvent({
                message: 'Failed to run offering top-up checker',
                topic: AuditScope.ERROR,
                data: [{ error: serializeError(error), businessID, offeringId }],
            });
        }
        OfferingTopUpChecker.logger.log(`Finished top-up checker for offering ${offeringId}`);
    }

    @OnQueueFailed({ name: 'offeringTopUpChecker' })
    jobFailure(job: Job) {
        AuditService.publishEvent({
            message: 'Failed to process offering top-up checker job',
            data: [job],
            topic: AuditScope.ERROR,
        });
    }
}

